function canSegment(text, words) {
  const vocab = new Set(words)
  const lengths = [...new Set(words.map(w => w.length))].sort((a, b) => a - b)
  const ok = new Array(text.length + 1).fill(false)
  ok[0] = true
  for (let end = 1; end <= text.length; end++) {
    for (const size of lengths) {
      if (size > end) break
      if (ok[end - size] && vocab.has(text.slice(end - size, end))) {
        ok[end] = true
        break
      }
    }
  }
  return ok[text.length]
}

