def can_segment(text, words):
    vocab = set(words)
    lengths = sorted({len(w) for w in vocab})
    ok = [False] * (len(text) + 1)
    ok[0] = True
    for end in range(1, len(text) + 1):
        for size in lengths:
            if size > end:
                break
            if ok[end - size] and text[end - size:end] in vocab:
                ok[end] = True
                break
    return ok[len(text)]
